+// confinedRel refuses a path that is not a clean project-relative path.
+func confinedRel(rel string) error {
+	if rel == "" || filepath.IsAbs(rel) {
+		return fmt.Errorf("%q is not a clean project-relative path", rel)
+	}
+	for _, part := range strings.Split(rel, "/") {
+		if part == "" || part == "." || part == ".." {
+			return fmt.Errorf("%q is not a clean project-relative path", rel)
+		}
+	}
+	return nil
+}
+
 // fetch is a file's content from the overlay of files not yet written, or from the disk.
 func fetch(root string, overlay map[string][]byte, rel string) ([]byte, error) {
+	if err := confinedRel(rel); err != nil {
+		return nil, err
+	}
 	if b, ok := overlay[rel]; ok {
 		return b, nil
 	}
-	return os.ReadFile(filepath.Join(root, rel))
+	canonical, err := filepath.EvalSymlinks(root)
+	if err != nil {
+		return nil, err
+	}
+	resolved, err := filepath.EvalSymlinks(filepath.Join(canonical, rel))
+	if err != nil {
+		return nil, err
+	}
+	inside, err := filepath.Rel(canonical, resolved)
+	if err != nil || inside == ".." || strings.HasPrefix(inside, ".."+string(filepath.Separator)) {
+		return nil, fmt.Errorf("%q resolves outside the project", rel)
+	}
+	return os.ReadFile(resolved)
 }

